<template><div><PageHeader title="Create batch" description="Set up the cohort, trainer, schedule and capacity."><template #actions><RouterLink to="/app/batches" class="btn secondary">Cancel</RouterLink></template></PageHeader><div class="card"><div class="form-section"><h3>Batch details</h3><p>Connect the new cohort to a course and define operating dates.</p><div class="form-grid"><div class="field"><label>Batch name</label><input class="input" v-model="form.name"></div><div class="field"><label>Batch code</label><input class="input" v-model="form.code"></div><div class="field"><label>Course</label><select class="select" v-model="form.course"><option v-for="c in courses" :key="c.id">{{c.name}}</option></select></div><div class="field"><label>Capacity</label><input class="input" type="number" v-model="form.capacity"></div><div class="field"><label>Start date</label><input class="input" type="date" v-model="form.start"></div><div class="field"><label>End date</label><input class="input" type="date" v-model="form.end"></div></div></div><div class="form-section"><h3>Trainer & delivery</h3><p>Assign ownership and delivery format.</p><div class="form-grid"><div class="field"><label>Trainer</label><select class="select" v-model="form.trainer"><option v-for="t in trainers" :key="t.id">{{t.name}}</option></select></div><div class="field"><label>Location</label><input class="input" v-model="form.location" placeholder="Lab 02 / Online"></div><div class="field"><label>Delivery mode</label><select class="select" v-model="form.mode"><option>In person</option><option>Online</option><option>Hybrid</option></select></div><div class="field"><label>Status</label><select class="select"><option>planned</option><option>active</option></select></div></div></div><div class="form-section"><h3>Schedule</h3><p>Define recurring session times.</p><div class="form-grid"><div class="field"><label>Days</label><input class="input" value="Mon, Wed, Fri"></div><div class="field"><label>Time</label><input class="input" value="10:00 AM – 12:00 PM"></div></div></div><div class="form-actions"><RouterLink to="/app/batches" class="btn secondary">Cancel</RouterLink><button class="btn primary" @click="save">Create batch</button></div></div></div></template>
<script setup lang="ts">import {reactive} from 'vue';import {useRouter} from 'vue-router';import PageHeader from '../components/PageHeader.vue';import {courses,trainers} from '../data/mock';import {useToast} from '../composables/useToast';const router=useRouter();const {push}=useToast();const form=reactive({name:'Laravel Fundamentals — Sep C',code:'2026-09-C',course:courses[0].name,capacity:30,start:'2026-09-24',end:'2026-10-08',trainer:trainers[0].name,location:'Lab 02',mode:'In person'});function save(){push('Batch created successfully.');router.push('/app/batches')}</script>
